create table countries (
    country_id    serial primary key,
    country_name  text not null,
    country_code  text,
    continent     text,
    currency      text,
    language      text,
    phone_code    text,
    is_active     boolean default true
);

create table cities (
    city_id       serial primary key,
    city_name     text not null,
    country_id    int  not null references countries(country_id),
    region        text,
    population    int,
    postal_zone   text,
    is_capital    boolean default false,
    timezone      text
);

create table addresses (
    address_id    serial primary key,
    street        text not null,
    building      text,
    apartment     text,
    postal_code   text,
    city_id       int  not null references cities(city_id),
    latitude      decimal(9,6),
    longitude     decimal(9,6),
    notes         text
);

create table publishers (
    publisher_id    serial primary key,
    publisher_name  text not null,
    founded_year    int,
    website         text,
    email           text,
    phone           text,
    country         text,
    address         text
);

create table library_branches (
    branch_id     serial primary key,
    branch_name   text not null,
    address       text,
    phone         text,
    email         text,
    city          text,
    open_time     time    default '08:00:00',
    close_time    time    default '20:00:00',
    is_active     boolean default true
);

create table books (
    book_id        serial primary key,
    isbn           text not null,
    title          text not null,
    publisher_id   int  references publishers(publisher_id),
    publish_year   int,
    edition        int  default 1,
    language       text default 'english',
    total_pages    int,
    category       text,
    description    text,
    price          numeric(10,2)
);

create table authors (
    author_id     serial primary key,
    first_name    text not null,
    last_name     text not null,
    nationality   text,
    birth_date    date,
    email         text,
    country       text,
    bio           text
);

create table genres (
    genre_id         serial primary key,
    genre_name       text not null,
    description      text,
    parent_genre_id  int  references genres(genre_id),
    is_active        boolean default true
);

create table book_copies (
    copy_id        serial primary key,
    book_id        int     not null references books(book_id),
    branch_id      int     not null references library_branches(branch_id),
    condition      text    default 'good',
    is_available   boolean default true,
    acquired_date  date    default current_date,
    location_code  text,
    notes          text
);

create table member_categories (
    category_id    serial primary key,
    category_name  text         not null,
    max_books      int          not null default 3,
    loan_days      int          not null default 14,
    daily_fine     numeric(8,2) not null default 0.50,
    late_fee_cap   numeric(8,2),
    description    text,
    is_active      boolean default true
);

create table members (
    member_id         serial primary key,
    first_name        text not null,
    last_name         text not null,
    email             text,
    phone             text,
    address           text,
    category_id       int  not null references member_categories(category_id),
    membership_date   date default current_date,
    expiry_date       date,
    is_active         boolean default true
);

create table staff (
    staff_id      serial primary key,
    first_name    text not null,
    last_name     text not null,
    email         text not null unique,
    phone         text,
    role          text    default 'librarian',
    branch_id     int     references library_branches(branch_id),
    hire_date     date    default current_date,
    salary        numeric(12,2),
    is_active     boolean default true
);

create table loans (
    loan_id        serial primary key,
    copy_id        int  not null references book_copies(copy_id),
    member_id      int  not null references members(member_id),
    staff_id       int  references staff(staff_id),
    loan_date      date not null default current_date,
    due_date       date not null,
    return_date    date,
    status         text default 'active',
    notes          text,
    loan_duration  int  generated always as (due_date - loan_date) stored
);

create table fines (
    fine_id        serial primary key,
    loan_id        int          not null references loans(loan_id),
    amount         numeric(10,2) not null,
    issued_date    date         not null default current_date,
    paid_date      date,
    status         text default 'unpaid',
    fine_type      text default 'overdue',
    days_overdue   int
);

create table reservations (
    reservation_id  serial primary key,
    book_id         int     not null references books(book_id),
    member_id       int     not null references members(member_id),
    branch_id       int     not null references library_branches(branch_id),
    reserved_date   date    not null default current_date,
    expiry_date     date    not null,
    status          text    default 'pending',
    notified        boolean default false,
    queue_position  int
);

create table book_authors (
    book_id    int not null references books(book_id) on delete cascade,
    author_id  int not null references authors(author_id) on delete cascade,
    primary key (book_id, author_id)
);

create table book_genres (
    book_id   int not null references books(book_id) on delete cascade,
    genre_id  int not null references genres(genre_id) on delete cascade,
    primary key (book_id, genre_id)
);

