-- sql basic queries CRUD (Create, Read, Update, Delete) 

-- 1
select member_id, first_name, last_name, email,membership_date, expiry_date from members where is_active = true order by last_name asc;
--2
values ('978-3-16-148410-0', 'Introduction to Databases', 1, 2022, 1, 'english', 450, 'Technology', 49.99);
--3
update loans set status = 'overdue'where due_date < current_date and status = 'active' and return_date is null;
--4
delete from reservations where status = 'cancelled' and reserved_date < current_date - interval '1 year';
--5
select loan_id, member_id, loan_date, due_date, status from loans where status = 'overdue' order by due_date asc;

-- aggregations and grouping 

--1
select category_id, count(member_id) as total_members from members group by category_id order by total_members desc;
--2
select status, count(fine_id) as total_fines, sum(amount) as total_amount from fines group by status having count(fine_id) > 2;
--3 
select status, count(loan_id) as total_loans, avg(loan_duration) as avg_duration, sum(loan_duration) as total_days from loans group by status;

-- joins 
select l.loan_id, m.first_name, m.last_name, l.loan_date, l.status from loans l 
inner join members m on l.member_id = m.member_id;
select m.member_id, m.first_name, m.last_name, l.loan_id, l.status from members m 
left join loans l on m.member_id = l.member_id;
select b.title, bc.copy_id, bc.condition, bc.is_available from book_copies bc 
right join books b on bc.book_id = b.book_id;
select m.first_name, m.last_name, r.reservation_id, r.status from members m 
full outer join reservations r on m.member_id = r.member_id;
select l.loan_id, m.first_name, m.last_name, f.amount, f.status from loans l 
join members m on l.member_id = m.member_id join fines f on l.loan_id = f.loan_id;

--subqueris
--1
select first_name, last_name from members 
where category_id = (select category_id from member_categories where category_name = 'Student');
--2
select title from books where book_id in (select book_id from book_copies where is_available = true);
--3
select member_id, first_name, last_name from members
where member_id not in (select distinct member_id from loans);
--4
select loan_id, amount from fines f 
where amount > (select avg(amount) from fines where status = f.status);
--5 
select loan_id, member_id, (select count(*) from fines where loan_id = l.loan_id) as fine_count from loans l;

--Integration of Functions and Views

--1 view
create view active_loans_view as select l.loan_id, m.first_name, m.last_name, l.loan_date, l.due_date, l.status 
from loans l join members m on l.member_id = m.member_id where l.status = 'active';

select * from active_loans_view;
--2 function
create or replace function get_member_fines(p_member_id int) returns numeric as $$ begin return (select coalesce(sum(f.amount), 0) 
from fines f join loans l on f.loan_id = l.loan_id where l.member_id = p_member_id); end; $$ language plpgsql;

-- Triggers & Procedures

--1
create or replace function trg_insert_loan() 
	returns trigger as $$
	begin 
	update book_copies set is_available = false 
	where copy_id = NEW.copy_id; 
	return NEW; 
	end; 
	$$ language plpgsql;

create trigger trg_loan_insert 
after insert on loans 
for each row execute function trg_insert_loan();

--2 
create or replace function trg_update_loan() 
	returns trigger as $$ 
	begin 
	update book_copies set is_available = true
	where copy_id = NEW.copy_id; 
	return NEW; 
	end; 
	$$ language plpgsql;

create trigger trg_loan_update 
after update on loans 
for each row execute function trg_update_loan();

--3 
create or replace function trg_delete_fine() 
	returns trigger as $$ 
	begin 
	raise notice 'Fine deleted'; 
	return OLD; 
	end; 
	$$ language plpgsql;`

create trigger trg_fine_delete 
before delete on fines 
for each row execute function 
trg_delete_fine();

--4 
create or replace procedure add_fine(p_loan_id int, p_amount numeric) 
	language plpgsql as $$ 
	begin 
	values (p_loan_id, p_amount, current_date, 'unpaid', 'overdue'); 
	end; 
	$$;

call add_fine(1, 10.00);

